"""Verify built assets and publish a local-only, concise feature gallery."""
from pathlib import Path
import hashlib, json, shutil, subprocess, sys
root=Path(__file__).resolve().parents[1];out=root/'docs/agent-work/orda-perks'
read=lambda name:json.loads((out/name).read_text(encoding='utf8'))
logic,browser,assets=[read(name)for name in ['logic.json','browser.json','assets.json']]
assert logic['status']==browser['status']=='passed' and not browser['errors']
assert 'built in' in(out/'build.log').read_text(encoding='utf8',errors='replace')
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
for row in assets:
 assert sha(Path.home()/'Downloads'/row['source'])==row['sourceSha256']
 assert sha(root/row['path'])==sha(root/'dist'/row['path'].removeprefix('public/'))
summary={'status':'passed','rules':{'juggernog':{'price':2500,'hits':5,'baseHits':3},'speedcola':{'price':3000,'reloadDurationMultiplier':.5},'doubletap':{'price':2000,'fireRateMultiplier':4/3,'ballisticBulletsPerAmmo':2,'energyChainMultiplier':1},'pap':{'price':5000,'processSeconds':5,'claimSeconds':10,'damageMultiplier':2,'magazineMultiplier':2,'repeatUpgrade':False},'wunderwaffe':{'source':'Mystery Box','ammo':'3/15','upgraded':'DG-3 JZ,6/30','chainLimit':10,'linkRangeMetres':5,'bossDamage':600,'upgradedBossDamage':1200}},'controls':'Square / X contextual use, reload away from stations; phone USA','assets':[{k:r[k]for k in ['id','bytes','triangles','meshes','sourceSha256']}for r in assets],'tests':{'logic':logic['checks'],'browser':browser['checks'],'typecheck':'passed','build':'passed','errors':browser['errors']},'limits':['Mixed WaW/BO2/Minecraft supplied models: classic BO2-inspired effects, not an exact port of one Call of Duty release.','Three usable perk flavours with drinking animations; all five supplied bottles displayed. PHD and Quick Revive bottles are props; no new revive or self-explosion system.','Three base hits preserved per user instruction; Jugger raises them to five. Custom bosses take bounded electrical damage rather than unconditional instant death.','Single weapon inventory preserved. Unclaimed Pack reward is lost; fallback USP45. No repeat Pack attachments or power-switch quest.','Gamepads were browser-mapped simulations; no physical-controller session. No fresh FPS benchmark.'],'sources':[{'title':'Classic Black Ops II perk prices and roles','url':'https://www.gamerguides.com/call-of-duty-black-ops-ii/guide/zombies-guide/zombies-mode/overview/'},{'title':'Wunderwaffe chain and ammunition references','url':'https://callofduty.fandom.com/wiki/Wunderwaffe_DG-2'},{'title':'Treyarch: perk effects vary by Zombies release','url':'https://www.treyarch.com/game-intel/2020/10/Black_Ops_Cold_War_Zombies_Gameplay_Guide'}],'screenshots':['speed-cola.png','drink.png','wunderwaffe.png']}
(out/'verification.json').write_text(json.dumps(summary,indent=2,ensure_ascii=False),encoding='utf8')
(out/'README.md').write_text('''# Orda — perk, Pack-a-Punch e Wunderwaffe

Jugger-Nog2500: da3 a5 impatti validi. Speed Cola3000: ricariche e inserimenti a metà tempo, clip riprodotte a velocità doppia. Double Tap2.0 a2000: cadenza+33% e due proiettili balistici per una munizione, senza duplicare raggi o catene. Bevuta di2s prima dell’attivazione; effetti permanenti fino alla morte, nessun doppio acquisto.

Pack-a-Punch5000: deposito dell’arma corrente per5s, ritiro riservato al proprietario entro10s; danno e caricatore raddoppiati, munizioni rifornite. Arma depositata inutilizzabile. Upgrade singolo, perso cambiando arma. Mancato ritiro: arma persa e ritorno alla USP45, adattamento all’inventario singolo esistente.

Wunderwaffe DG-2 nella Mystery Box di Orda:3/15, catena fino10 nemici diversi, portata fra vicini5m e controllo coperture. Elimina i comuni;600 danni ai boss personalizzati. Pack: DG-3 JZ6/30, boss1200, ricarica4,7s. Niente fuoco amico né raddoppio catena Double Tap. La rotazione di Sparatoria resta invariata.

I sei file forniti sono utilizzati: quattro distributori, set delle cinque bottiglie e arma FPS. Tre gusti utilizzabili (Jugger, Speed, Double Tap); PHD e Quick Revive restano bottiglie decorative, senza aggiungere un sistema di rianimazione o danni autoinflitti. Macchine già alimentate; nessuna nuova missione elettrica. Modelli originali Downloads invariati; crediti CC BY4.0 in public/assets/orda/perks/CREDITS.md. Asset condivisi fra visuali, batch per materiale e LOD Double Tap8mm.

Quadrato/X vicino alle stazioni per comprare, depositare o ritirare; lontano ricarica. Telefono USA. Test mirati di autorità, input pad simulati e telefono attraverso socket, bevuta e modello Wunderwaffe nel renderer reale, cinque visuali, typecheck e build. Nessun nuovo benchmark FPS. Nessun commit, push o deploy.
''',encoding='utf8')
figures=''.join(f'<figure><img src="{name}" alt="{label}"><figcaption>{label}</figcaption></figure>'for name,label in [('speed-cola.png','Speed Cola · distributore originale e acquisto a punti'),('drink.png','Bottiglia originale · animazione della bevuta'),('wunderwaffe.png','Wunderwaffe DG-3 JZ · modello originale in prima persona')])
(out/'index.html').write_text('''<!doctype html><html lang="it"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Orda · Perk e Wunderwaffe</title><style>body{margin:0;background:#101b1b;color:#ece9dc;font:17px/1.6 system-ui}main{max-width:1250px;margin:auto;padding:28px}h1,strong,a{color:#e5bb72}table{border-collapse:collapse;width:100%;max-width:1050px}td,th{text-align:left;border-bottom:1px solid #51615a;padding:12px}figure{margin:25px 0;border:1px solid #51615a}img{display:block;width:100%}figcaption{padding:12px}p{max-width:1050px}</style><main><h1>Perk, Pack-a-Punch e Wunderwaffe</h1><p>Usa <strong>Quadrato / X</strong> vicino ai distributori e al Pack-a-Punch; sul telefono premi <strong>USA</strong>. Restano50 punti per uccisione e950 per la Mystery Box.</p><table><tr><th>Oggetto</th><th>Costo</th><th>Effetto</th></tr><tr><td>Jugger-Nog</td><td>2500</td><td>Da3 a5 colpi per morire</td></tr><tr><td>Speed Cola</td><td>3000</td><td>Ricariche in metà tempo</td></tr><tr><td>Double Tap2.0</td><td>2000</td><td>Cadenza+33%, due proiettili balistici per munizione</td></tr><tr><td>Pack-a-Punch</td><td>5000</td><td>Deposita, attendi5s e ritira: danno e caricatore×2</td></tr><tr><td>Wunderwaffe DG-2</td><td>Mystery Box</td><td>Scarica a catena fino10 nemici;3/15, Pack6/30</td></tr></table><p>Modelli forniti integrati, bottiglie e bevuta, armi e perk sull’HUD. Le bottiglie PHD/Quick Revive sono decorative: questa integrazione mantiene l’eliminazione e l’inventario singolo di Orda. Effetti ispirati ai classici, con resistenza base3 come già richiesto.</p>'''+figures+'''<p>Test mirati, pad e telefono, cinque visuali, typecheck e build superati. <a href="verification.json">Dettagli, fonti e limiti</a> · <a href="/">Party Game</a></p><p>Asset CC BY4.0, crediti conservati. Nessun commit, push o deploy.</p></main></html>''',encoding='utf8')
subprocess.run([sys.executable,str(root/'scripts/orda-box-polish-finalize.py')],cwd=root,check=True)
dest=root/'dist/orda-perks';dest.mkdir(parents=True,exist_ok=True)
for name in ['index.html','verification.json',*summary['screenshots']]:shutil.copy2(out/name,dest/name)
print('Orda perks: source hashes unchanged, built assets verified; local gallery ready.')
